def wrap_deg(a):
    while a > 180.0:
        a -= 360.0
    while a <= -180.0:
        a += 360.0
    return a


def clamp(v, lo, hi):
    if v < lo:
        return lo
    if v > hi:
        return hi
    return v


def enemy_can_self_right(enemy):
    for slot, w in enemy.weapons.items():
        if w["health"] > 0.0:
            t = w["type"]
            if t == "hammer" or t == "lifter":
                return True
            if t == "flipper" and w["shots_left"] > 0:
                return True
    return False


def steer_to(me, tx, ty, max_fwd, reverse=False):
    b = bearing_to(tx, ty)
    if reverse:
        b = wrap_deg(b + 180.0)
    turn = clamp(b / 32.0 - me.turn_rate / 160.0, -1.0, 1.0)
    if abs(b) > 55.0:
        fwd = 0.0
    else:
        fwd = max_fwd * cos(radians(b))
    if reverse:
        fwd = -fwd
    left = clamp(fwd - turn, -1.0, 1.0)
    right = clamp(fwd + turn, -1.0, 1.0)
    return (left, right)


def drive(me, enemy, arena):
    mem = me.memory
    if "init" not in mem:
        mem["init"] = True
        mem["stuck_t"] = 0.0
        mem["backoff_until"] = 0.0
        mem["flank_sign"] = 1.0
        mem["last_log"] = -10.0

    if not me.can_drive:
        return (0.0, 0.0)

    dist = distance_to(enemy.x, enemy.y)
    w_front = me.weapons.get("front")
    spinner_alive = (w_front is not None) and (w_front["health"] > 0.0)
    rpm_frac = 0.0
    if spinner_alive and w_front["max_rpm"] > 0.0:
        rpm_frac = abs(w_front["rpm"]) / w_front["max_rpm"]

    # Periodic diagnostic log
    if arena.time - mem["last_log"] >= 15.0:
        mem["last_log"] = arena.time
        print(f"t={arena.time:.1f} d={dist:.2f} rpm={rpm_frac:.2f} inv={me.inverted} hp={me.health:.2f} ehp={enemy.health:.2f}")

    # 1. If enemy is helplessly KO-counting, keep safe distance so we do not knock them upright
    can_sr = enemy_can_self_right(enemy)
    enemy_helpless = (
        (enemy.inverted and (not enemy.invertible) and (not can_sr) and (not enemy.righting))
        or (enemy.on_side and (not can_sr) and (not enemy.righting))
    )
    if enemy_helpless:
        b_e = bearing_to(enemy.x, enemy.y)
        turn = clamp(b_e / 30.0 - me.turn_rate / 160.0, -1.0, 1.0)
        if dist < 2.2:
            fwd = -0.6
        elif dist > 3.2:
            fwd = 0.4
        else:
            fwd = 0.0
        return (clamp(fwd - turn, -1.0, 1.0), clamp(fwd + turn, -1.0, 1.0))

    # 2. Bubble safety for front spinner
    rad_h = radians(me.heading)
    hx = cos(rad_h)
    hy = sin(rad_h)
    if spinner_alive:
        tip_x = me.x + 0.69 * hx
        tip_y = me.y + 0.69 * hy
        tip_r = hypot(tip_x, tip_y)
        facing_out = (me.x * hx + me.y * hy) > 0.0
        if tip_r > arena.radius - 0.28 and facing_out:
            b_c = bearing_to(0.0, 0.0)
            turn = clamp(b_c / 30.0 - me.turn_rate / 160.0, -1.0, 1.0)
            return (clamp(-0.55 - turn, -1.0, 1.0), clamp(-0.55 + turn, -1.0, 1.0))

    # 3. Backup mode if front spinner is destroyed: fight backwards with back wedge
    if not spinner_alive:
        use_back_wedge = (not me.inverted) and ("back" in me.wedges) and (me.wedges["back"]["life"] > 0.05)
        return steer_to(me, enemy.x, enemy.y, 1.0, reverse=use_back_wedge)

    # 4. Stuck / grind detection: back off briefly to get a fresh bite and spin-up
    if dist < 1.25 and abs(me.speed) < 0.45:
        mem["stuck_t"] += 0.05
    else:
        mem["stuck_t"] = max(0.0, mem["stuck_t"] - 0.1)

    if mem["stuck_t"] > 1.4:
        mem["stuck_t"] = 0.0
        mem["backoff_until"] = arena.time + 0.7
        mem["flank_sign"] = -mem["flank_sign"]

    if arena.time < mem["backoff_until"]:
        b_e = bearing_to(enemy.x, enemy.y)
        turn = clamp(b_e / 30.0 - me.turn_rate / 160.0, -1.0, 1.0)
        my_r = hypot(me.x, me.y)
        if my_r > arena.radius - 1.2:
            return steer_to(me, 0.0, 0.0, 0.8, reverse=False)
        return (clamp(-0.75 - turn, -1.0, 1.0), clamp(-0.75 + turn, -1.0, 1.0))

    # 5. Spin-up spacing when rotor is slow
    if rpm_frac < 0.48 and arena.time < 110.0:
        if dist < 2.3:
            my_r = hypot(me.x, me.y)
            if my_r < arena.radius - 1.3:
                b_e = bearing_to(enemy.x, enemy.y)
                turn = clamp(b_e / 28.0 - me.turn_rate / 160.0, -1.0, 1.0)
                return (clamp(-0.7 - turn, -1.0, 1.0), clamp(-0.7 + turn, -1.0, 1.0))
        elif dist > 3.2:
            # Arc gently while spinning up
            e_to_me = atan2(me.y - enemy.y, me.x - enemy.x)
            tx = enemy.x + 2.8 * cos(e_to_me + mem["flank_sign"] * 0.5)
            ty = enemy.y + 2.8 * sin(e_to_me + mem["flank_sign"] * 0.5)
            return steer_to(me, tx, ty, 0.65, reverse=False)

    # 6. Flanking vs Direct Attack
    # Compute angle from enemy's heading to us
    ang_e_to_me = degrees(atan2(me.y - enemy.y, me.x - enemy.x))
    e_bear = wrap_deg(ang_e_to_me - enemy.heading)

    enemy_has_front_wedge = ("front" in enemy.wedges) and (enemy.wedges["front"]["life"] > 0.05)

    # Lead enemy slightly based on closing time
    lead_t = clamp(dist / 6.0, 0.0, 0.35)
    tx = enemy.x + enemy.vx * lead_t
    ty = enemy.y + enemy.vy * lead_t

    # If enemy has a front wedge and is facing us at medium range, curve around to flank
    if enemy_has_front_wedge and 1.25 < dist < 3.4 and abs(e_bear) < 42.0:
        side = 1.0 if e_bear >= 0.0 else -1.0
        if abs(e_bear) < 8.0:
            side = mem["flank_sign"]
        e_rad = radians(enemy.heading)
        # Aim toward enemy's flank
        offset = 0.75 * side
        tx = enemy.x - 0.15 * cos(e_rad) - offset * sin(e_rad)
        ty = enemy.y - 0.15 * sin(e_rad) + offset * cos(e_rad)
        # Keep target safely inside arena
        tr = hypot(tx, ty)
        if tr > arena.radius - 1.0:
            scale = (arena.radius - 1.0) / tr
            tx *= scale
            ty *= scale

    return steer_to(me, tx, ty, 1.0, reverse=False)


