        mem["stuck_t"] = 0.0
        mem["realign_until"] = arena.time + 0.45

    if arena.time < mem["realign_until"]:
        b_e = bearing_to(enemy.x, enemy.y)
        turn = clamp(b_e / 28.0 - me.turn_rate / 160.0, -1.0, 1.0)
        return (clamp(-0.9 - turn, -1.0, 1.0), clamp(-0.9 + turn, -1.0, 1.0))

    # 4. Full-speed aggressive charge with slight target lead
    lead_t = clamp(dist / 9.0, 0.0, 0.22)
    tx = enemy.x + enemy.vx * lead_t
    ty = enemy.y + enemy.vy * lead_t
    tx, ty = safe_point(tx, ty, arena.radius - 0.55)
    return steer_to(me, tx, ty, 1.0, reverse=False, turn_cut=58.0)


def weapons(me, enemy, arena):
    wf = me.weapons.get("front")
    if wf is None or wf["health"] <= 0.0:
        return None

    # Self-right immediately if inverted and at rest with flipper ready
    if me.inverted and (not me.airborne) and (not me.righting) and wf["ready"]:
        return self_right()

    if me.airborne or me.inverted or me.on_side or me.righting:
        return None

    if not wf["ready"]:
        return None

    if enemy.airborne or enemy.righting or enemy.on_side:
        return None

    if enemy.inverted and (not enemy.invertible):
        return None

    if is_enemy_helpless(enemy):
        return None

    if not enemy_in_flipper_zone(me, enemy):
        return None

    # Against a 2mm edge, avoid wasting a flip if we are clearly losing the closing speed tie
    if enemy_has_2mm_edge(me, enemy):
        dx = enemy.x - me.x
        dy = enemy.y - me.y
        d = hypot(dx, dy)
        if d > 0.001:
            my_v = (me.vx * dx + me.vy * dy) / d
            en_v = -(enemy.vx * dx + enemy.vy * dy) / d
            if my_v < en_v - 0.15:
                return None

    return flip("front")
